cat=json.loads((P/'catalog.js').read_text().split('=',1)[1].rstrip(';\n'));cat=[b for b in cat if b.get('readable',True)];manifest=json.loads((P/'content-manifest.json').read_text());urls=[]
esc=lambda s:html.escape(str(s),quote=True)
