nav='<nav>'+link('', '互動閱讀')+link('library.html','完整書目')+link('about.html','關於拾頁')+link('privacy.html','隱私政策')+link('contact.html','聯絡與勘誤')+'</nav>'
def page(path,title,body,description='',advertising=False,schema=None):
 urls.append(path);canonical=href(path);extra=''
 if path.startswith('stories/') and path.endswith('/index.html'):
  book=next((b for b in cat if path=='stories/'+b['id']+'/index.html'),None)
  if book and book.get('coverage'):
   v=book['coverage'];body+=f'<section class="note"><h2>正文詞表覆蓋率</h2><p>以英文出現次數計，精確字形可對到參考第 1–{v["referenceLevel"]} 級：{v["exactCoverage"]}%。人名、變化形與未匹配詞未猜測還原；這不是全文難度認證。</p>'+link('vocabulary.html','查看方法與逐書報告')+'</section>'
  if book and book.get('series'):
   body+='<section class="note"><h2>系列進度</h2><p>目前已上架第一卷，共 25 章。第 2 卷尚未公告日期；本站不把規劃中的卷數計入可讀內容。</p></section>'
 if ADS_ENABLED and advertising:extra=f'<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client={PUB}" crossorigin="anonymous"></script>'
 if schema:extra+='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')+'</script>'
 out=f'<!doctype html><html lang="zh-Hant"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}｜拾頁 StorySteps</title><meta name="description" content="{esc(description or title)}"><meta name="google-adsense-account" content="{PUB}"><link rel="canonical" href="{canonical}"><link rel="stylesheet" href="{posixpath.relpath("public-reading.css",str(Path(path).parent))}">{extra}</head><body><header>{link("", "拾頁 StorySteps")}{nav}</header><main>{body}</main><footer><p>依自己的步調閱讀。前 5 章可直接閱讀；互動版提供查詞、收藏、朗讀與後續免費解鎖。</p>{nav}<p>© 2026 StorySteps · AI 輔助創作與翻譯 · 校訂狀態請見各書說明</p></footer></body></html>'
 p=P/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(out)
chapters={b['id']:json.loads(gzip.decompress((P/manifest['books'][b['id']]['url']).read_bytes())) for b in cat}
for b in cat:
 id=b['id'];path=f'stories/{id}/';cover=f'<img class="cover" loading="lazy" src="{href(b["cover"].removeprefix("./"))}" alt="{esc(b["zh"])} AI 插畫封面">' if b.get('cover') else ''
 toc=[]
 for i,c in enumerate(chapters[id],1):
  label=f'第 {i} 章　{c["zh"]}'
  toc.append('<li>'+ (link(path+f'chapter-{i}.html',label) if i<=5 else link('?book='+id+'&chapter='+c['id'],label+' · 互動版免費解鎖'))+'</li>')
  if i>5:continue
  paras=''.join(f'<section class="chapter-section"><p class="en" lang="en">{esc(p["en"])}</p><p class="zh">{esc(p["zh"])}</p></section>' for p in c['paragraphs'])
  words=''.join(f'<tr><td lang="en">{esc(w["word"])}</td><td>{esc(w.get("meaning",""))}</td></tr>' for w in c['words'])
  quiz=''
  for q in c['questions']:
   opts=''.join(f'<li>{esc(o)}</li>' for o in q['options']);quiz+=f'<section><h3 lang="en">{esc(q["question"])}</h3><ol type="A" lang="en">{opts}</ol><details><summary>查看答案與說明</summary><p>答案：{chr(65+q["answer"])}。{esc(q["explanation"])}</p></details></section>'
  prev=link(path+(f'chapter-{i-1}.html' if i>1 else ''),'上一章' if i>1 else '回章節目錄');nxt=link(path+f'chapter-{i+1}.html','下一章') if i<5 else link('?book='+id+'&chapter='+chapters[id][5]['id'],'到互動版免費解鎖第 6–9 章')
  body=f'<p>{link("library.html","完整書目")} / {link(path,b["zh"])}</p><h1>{esc(c["zh"])}</h1><h2 lang="en">{esc(c["title"])}</h2><p class="muted">{esc(b["zh"])} · 第 {i} / 25 章 · {esc(b["level"])} · 英中對照</p><a class="button" href="{href("?book="+id+"&chapter="+c["id"])}">用互動版查詞、朗讀與收藏</a><article>{paras}</article><h2>本章詞彙</h2><table><thead><tr><th>英文</th><th>中文</th></tr></thead><tbody>{words}</tbody></table>'+(f'<h2>閱讀理解</h2>{quiz}' if quiz else '<p class="note">本章目前提供正文與詞彙，閱讀理解題仍待補齊。</p>')+f'<nav class="chapter-nav">{prev}{nxt}</nav><p class="muted">發現文字或翻譯問題？{link("contact.html","回報勘誤")}。這份內容尚未標示為人工全章校訂完成。</p>'
  page(path+f'chapter-{i}.html',b['zh']+'｜第 '+str(i)+' 章 '+c['zh'],body,b['hook']+' 第 '+str(i)+' 章英中對照。',True)
 body=cover+f'<p class="muted">{esc(b["level"])} · {esc(b["genre"])}</p><h1>{esc(b["zh"])}</h1><p lang="en">{esc(b["title"])}</p><p>{esc(b["desc"])}</p><a class="button" href="{href(path+"chapter-1.html")}">直接讀第 1 章</a><a href="{href("?book="+id)}">開啟互動版書頁</a><p class="note">全文已上架・編輯校訂中。本書已收錄 25 章。已完成匯入與結構檢查，英文自然度、翻譯、情節與測驗仍需逐章編輯複核；不代表已完成真人編輯審閱。級距是目標詞的配詞範圍，不是全文詞彙難度保證。</p><h2>章節目錄</h2><ol>{"".join(toc)}</ol>'
 page(path+'index.html',b['zh'],body,b['hook'],True,{'@context':'https://schema.org','@type':'Book','name':b['zh'],'alternateName':b['title'],'inLanguage':['en','zh-Hant'],'description':b['desc'],'url':href(path+'index.html')})
cards=''.join(f'<article class="card"><p class="muted">{esc(b["level"])} · {esc(b["genre"])}</p><h2>{link("stories/"+b["id"]+"/",b["zh"])}</h2><p>{esc(b["hook"])}</p>{link("stories/"+b["id"]+"/chapter-1.html","免費讀第 1 章")}</article>' for b in cat)
page('library.html','分級英文故事完整書目',f'<h1>分級英文故事書庫</h1><section class="note"><h2>A／B 與閱讀方式</h2><p>A 本代表本站同級配詞前約 500 詞，B 本代表後約 500 詞（部分原表各 501 詞）；這是本站拆分方式，不是故事上下集。詞彙分級參考大考中心配合教育部 108 英語文課綱編修的《高中英文參考詞彙表》（官方六級）；本站第七級為自訂進階配詞。<a href="about.html#vocabulary-source">查看官方來源與分級說明</a>。每天讀一章，25 天讀完一本，餘下時間複習；同級 A、B 各讀一本，約兩個月接觸 1,000 個目標詞，並搭配間隔複習。同範圍可以選不同故事複習。先依興趣與級距選書，從第 1 章開始讀英文；需要時看中文，或到互動版查詞與朗讀，最後複習章末單字及已提供的測驗。</p></section><p>目前 {len(cat)} 本、{len(cat)*25} 章。每本前 5 章可直接讀取英中正文，不必登入或解鎖。其餘章節在互動版免費解鎖。</p><p>{link("editorial.html","內容製作與校訂狀態")}</p><div class="book-grid">{cards}</div>',f'{len(cat)} 本分級英文小說，免費試讀英中對照正文，包含詞彙與已收錄的閱讀測驗。')
page('about.html','關於拾頁', '<h1>關於拾頁 StorySteps</h1><p>拾頁是一個以故事陪伴英文閱讀的獨立學習網站，服務想透過情節練習閱讀的國高中生與其他英文學習者。</p><h2 id="vocabulary-source">分級與詞彙來源</h2><p>分級參考配合教育部 108 英語文課綱編修、由大學入學考試中心公布的《高中英文參考詞彙表》（111 學年度起適用）。官方參考表分六級，每級約 1,000 詞條；本站七個顯示級距、各書目標詞表與 A／B 拆分是專案學習安排，並非教育部官方分冊或官方認證。既有舊書配詞尚未逐項核對，不應將顯示級距理解為全文難度保證。</p><p><a href="https://www.ceec.edu.tw/xcepaper/cont?qperoid=0K220613903738311866&amp;sid=0K227548677326460907&amp;xsmsid=0J066588036013658199">大考中心：參考詞彙表編修說明</a></p><h2>每天一章的閱讀計畫</h2><p>A 本涵蓋同級前約 500 詞，B 本涵蓋後約 500 詞，依本站配詞順序拆分，部分原始配詞表各有 501 詞條。每天讀一章，25 天讀完一本，保留幾天複習，約一個月完成；兩個月讀同級 A、B 各一本，接觸約 1,000 個目標詞。讀過不代表熟記，請搭配測驗、生字本與間隔複習。此配詞說明適用於已標示 A／B 並核對 ID 的書籍。</p><h2>如何使用</h2><p>先選感興趣的故事，再選合適的目標詞級距。可以讀英文、對照繁體中文，在互動版點字查詞、收藏生字與朗讀。</p><p>七個顯示級距由 1000 以下至 6000–7000；它們代表配詞範圍，不是 CEFR 認證，也不保證每個字都落在該範圍。</p><h2>免費閱讀與營運</h2><p>目前不收閱讀費。每本前 5 章直接讀，後續每次免費解鎖 4 章。正式廣告未啟用前，互動版依設定提供免費替代解鎖。</p><h2>內容來源</h2><p>故事、翻譯與封面使用 AI 輔助製作，並由站主維護、篩選與處理勘誤。匯入及機器檢查不等於人工逐章校訂。我們不把機器檢查標示為真人編輯認證。</p><p>'+link('editorial.html','查看校訂方式與目前狀態')+' · '+link('contact.html','聯絡維護者')+'</p>')
page('privacy.html','資料與隱私','<h1>資料與隱私</h1><p>更新日期：2026 年 11 月 9 日。適用於拾頁 StorySteps。</p><h2>本機自動保存</h2><p>閱讀進度、生字、書架、句子收藏、設定、簽到與免費解鎖存在此瀏覽器。使用功能時自動保存，不須帳號。換裝置、換瀏覽器或清除網站資料可能看不到原來紀錄。XP 只作本機閱讀紀錄，不參加公開排行，不是購買或資格憑證。</p><h2>匯出、匯入與持續儲存</h2><p>下載備份由讀者主動操作。上次要求匯出時間不等於檔案已儲存成功；請自行確認下載項目。備份含學習紀錄，勿公開分享。匯入前顯示摘要並要求確認，採合併方式保留目前同項資料。網站依實際功能偵測提供持續儲存請求；獲准後仍不能避免手動清除或裝置遺失。</p><h2>雲端研究與文字回報暫停</h2><p>此版本不新增雲端閱讀事件或段落文字回報。舊版經選擇加入的研究樣本使用隨機瀏覽器代碼、事件、書名與章節位置，不等於完全匿名；保留既有 90 天刪除政策，只展示彙總數據。恢復前需確認經營者告知、未成年人同意與資料權利流程，不以過去選擇自動恢復。</p><h2>廣告與網站供應商</h2><p>正式展示與獎勵廣告都尚未啟用，此版本不自動載入 Google 廣告腳本。GitHub Pages 與 Cloudflare 仍處理正常連線所需資訊；只在你主動打開歷史統計時讀取既有彙總數據，不送出新的閱讀事件。</p><h2>公開聯絡與資料權利</h2><p>可透過聯絡頁向維護者提出查詢、停止處理或刪除既有資料等需求。GitHub 議題是公開管道，請只描述需求，勿貼個人資料、瀏覽器識別碼或整份備份。經營者將安排後續處理方式；在完整告知與適用流程確認前，不重新開放研究。</p><p>'+link('contact.html','聯絡與勘誤')+' · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub 隱私政策</a> · <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare 隱私政策</a></p>')
page('contact.html','聯絡與勘誤','''<h1>聯絡與勘誤</h1><p>拾頁由本專案 GitHub 儲存庫擁有者維護。內容勘誤、功能故障與一般合作詢問，可透過下方公開問題追蹤區傳達給維護者。</p><p><a class="button" href="https://github.com/tttoom580-ui/storysteps-preview/issues/new">在 GitHub 留下問題或聯絡需求</a></p><p>需要 GitHub 帳戶。送出後內容及帳戶名稱公開可見，請勿填入電話、密碼、付款資料、學習備份或其他個資。需要非公開聯絡時，請先只說明需求，由維護者安排後續方式；目前不提供站內私訊。</p><h2>內容勘誤請提供</h2><ul><li>書名、章節及固定網址。</li><li>有問題的英文句子、翻譯或測驗題。</li><li>你認為需要修改的地方。</li></ul><p>目前已暫停雲端段落文字回報；段落工具提供書名、章節與段落位置，供你自行決定是否到公開 GitHub 管道回報。頁尾的一般「意見回饋」目前只存本機，不會自動送達站主，因此正式聯絡請使用上方 GitHub 管道。</p>''')
page('editorial.html','內容製作與校訂狀態','''<h1>內容製作與校訂狀態</h1><p>故事與翻譯由 AI 輔助製作。維護者負責內容取捨、版本管理與勘誤。以下區分資料檢查和真人編輯審閱，避免讀者誤認。</p><h2>已做的檢查</h2><p>已比對公開書庫的書名、整本英中正文、章節全文及長段落；將發現大量重用段落或高重合文字的 4 本移出書目。已核對章節可讀性與資料結構。</p><h2>主打作品的第一輪校訂</h2><p>《雪谷的七種聲音》《沒有火種的修窯師》《零號月台的三條規則》各前五章已進行 AI 編輯逐章閱讀，處理英文自然度、中文對照、情節線索和題目歧義。這是第一輪 AI 校訂，並非真人編輯認證；全書其餘章節仍在校訂中。</p><h2>仍待完成</h2><p>機器比對不能證明故事情節完全獨創，也不能確保英文自然、翻譯正確或每一題都只有一個合理答案。現有書目仍待真人逐章閱讀與校訂。2026 年 11 月 9 日補齊原缺少測驗的 374 章，共新增 748 題正文理解練習草稿，包含情節問答與正文事件填空，附原文及中文段落證據；仍待教學品質複核。原有 20 個短章依既有情節補寫英中場景，並重新核算字數，不使用跨章複製段落湊篇幅。</p><h2>處理原則</h2><p>優先處理意思錯譯、題目答案矛盾、情節不連續與重複正文。經查證後修正；若需要重寫，保留舊稿並更新版本。尚未完成的真人審閱不會標示為已完成。</p>'''+link('contact.html','提出內容勘誤'))
# Honest launch notes and separate teacher / partner information.
